class Solution { public List<List<Integer>> minimumAbsDifference(int[] arr){Arrays.sort(arr);int minimum=Integer.MAX_VALUE;for(int i=1;i<arr.length;i++)minimum=Math.min(minimum,arr[i]-arr[i-1]);List<List<Integer>> answer=new ArrayList<>();for(int i=1;i<arr.length;i++)if(arr[i]-arr[i-1]==minimum)answer.add(Arrays.asList(arr[i-1],arr[i]));return answer;} }
